application.javascript:
const form = document.getElementById('booking-form');
const dateInput = document.getElementById('booking-date');
const list = document.getElementById('booking-list');
const confirmation = document.getElementById('booking-confirmation');
const error = document.getElementById('form-error');
const count = document.getElementById('booking-count');
const bookings = [];

function localDate(){
  const now = new Date();
  const offset = now.getTimezoneOffset() * 60000;
  return new Date(now.getTime() - offset).toISOString().slice(0,10);
}
dateInput.min = localDate();

function prettyDate(value){
  return new Date(value + 'T00:00:00').toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric',year:'numeric'});
}
function prettyTime(value){
  const [hours, minutes] = value.split(':');
  const d = new Date(); d.setHours(hours, minutes);
  return d.toLocaleTimeString([], {hour:'numeric', minute:'2-digit'});
}
function render(){
  list.innerHTML = '';
  if(!bookings.length){
    list.innerHTML = '<div class="empty-state"><span>◷</span><p>No appointments yet</p><small>Your confirmed bookings will appear here.</small></div>';
  } else bookings.forEach((booking,index)=>{
    const card = document.createElement('article');
    card.className = 'booking-card' + (booking.cancelled ? ' cancelled' : '');
    card.dataset.testid = 'booking'; card.dataset.status = booking.cancelled ? 'cancelled' : 'active';
    card.innerHTML = `<div class="booking-main"><div class="booking-icon">${booking.cancelled ? '×' : '◷'}</div><div><p class="booking-name" data-testid="booking-name-display"></p><p class="booking-meta">${booking.type} · ${prettyDate(booking.date)} at ${prettyTime(booking.time)}</p></div></div>`;
    card.querySelector('.booking-name').textContent = booking.name;
    if(booking.cancelled){ const label=document.createElement('span'); label.className='cancelled-label'; label.textContent='Cancelled'; card.append(label); }
    else { const button=document.createElement('button'); button.className='cancel-button'; button.dataset.testid='booking-cancel'; button.type='button'; button.textContent='Cancel'; button.addEventListener('click',()=>{bookings[index].cancelled=true;render()}); card.append(button); }
    list.append(card);
  });
  const active = bookings.filter(b=>!b.cancelled).length;
  count.textContent = `${active} booking${active===1?'':'s'}`;
}
form.addEventListener('submit', event=>{
  event.preventDefault(); error.textContent=''; confirmation.hidden=true;
  if(!form.reportValidity()) return;
  const data = new FormData(form); const chosen = data.get('date');
  if(chosen < localDate()){ error.textContent='Please choose today or a future date.'; dateInput.focus(); return; }
  const booking={name:data.get('name'),email:data.get('email'),date:chosen,time:data.get('time'),type:data.get('type'),cancelled:false};
  bookings.push(booking); render();
  confirmation.textContent=`Appointment confirmed for ${booking.name} on ${prettyDate(booking.date)} at ${prettyTime(booking.time)}.`; confirmation.hidden=false;
  form.reset(); dateInput.min=localDate(); confirmation.scrollIntoView({behavior:'smooth',block:'nearest'});
});
render();
